        note = f"low={fr['low']}  high={fr['high']}  mid={fr['mid']}   |   {fr['decision']}"
        draw_array(ax, arr, colors=colors,
                   title=f"Binary Search — target = {target}", note=note)
    return run_animation(_frame, n_frames=len(frames), interval=1300, figsize=(9.5, 3.0))

